package suft.android.hafiz.domain

import java.io.InputStream

/** An ayah resembling another; [strength] 0–100 is the share of words the two have in common. */
data class SimilarAyah(val ayah: Int, val strength: Int)

/**
 * Mutashabihat: pairs of ayahs that closely resemble each other, from Aswaatul Qurraa
 * (assets/mutashabihat.txt, generated by tools/mutashabihat.py). Ayahs are global indices into [Quran].
 */
class Mutashabihat private constructor(private val similar: Array<List<SimilarAyah>>) {
    /** Ayahs resembling [ayah], most similar first (stable for ties); empty when it has none. */
    fun of(ayah: Int): List<SimilarAyah> = similar[ayah]

    companion object {
        private val WHITESPACE = Regex("\\s+")
        /** Lines `surah:ayah surah:ayah strength`; `#` comments and blank lines are skipped. */
        fun parse(input: InputStream, quran: Quran): Mutashabihat {
            val lists = Array(quran.ayahCount) { ArrayList<SimilarAyah>() }

            fun ayahAt(ref: String, n: Int): Int {
                val surah = ref.substringBefore(':').toIntOrNull()
                val ayah = ref.substringAfter(':', "").toIntOrNull()
                require(
                    surah != null && ayah != null &&
                        surah in 1..Quran.SURAH_COUNT && ayah in 1..quran.surahs[surah - 1].ayahCount,
                ) { "mutashabihat line $n: no ayah $ref" }
                return quran.surahs[surah - 1].firstAyah + ayah - 1
            }

            input.bufferedReader().useLines { lines ->
                lines.forEachIndexed { i, raw ->
                    val line = raw.trim()
                    if (line.isEmpty() || line.startsWith('#')) return@forEachIndexed
                    val n = i + 1
                    val parts = line.split(WHITESPACE)
                    require(parts.size == 3) { "mutashabihat line $n: $line" }
                    val a = ayahAt(parts[0], n)
                    val b = ayahAt(parts[1], n)
                    require(a != b) { "mutashabihat line $n: self-pair $line" }
                    val strength = parts[2].toIntOrNull()
                    require(strength != null && strength in 0..100) { "mutashabihat line $n: $line" }
                    lists[a] += SimilarAyah(b, strength)
                    lists[b] += SimilarAyah(a, strength)
                }
            }
            return Mutashabihat(Array(lists.size) { lists[it].sortedByDescending(SimilarAyah::strength) })
        }
    }
}
